    function offerGroupsOf(id){
      const full=OFFER_FULL[id];
      if(full) return full;
      const act=[["Дизайн",["Литые диски","LED-фары и ДХО","Рейлинги","Зеркала с электрорегулировкой и обогревом"]],["Безопасность",["Эра Глонасс","ABS / ESC","Подушки + шторки","Камера заднего вида","Задние датчики","TPMS","Isofix"]],["Комфорт",["Климат-контроль","Обогрев передних сидений","Бесключевой доступ","Круиз","EPB + AutoHold","Дистанционный запуск"]],["Мультимедиа",["Дисплей 12.3\"","Android Auto / CarPlay","Bluetooth / USB"]]];
      const prm=[["Дизайн",["Литые диски большей размерности","LED-оптика","Рейлинги","Электроскладывание зеркал","Панорамная крыша"]],["Безопасность",["Эра Глонасс","ABS / ESC","Подушки + шторки","Круговой обзор","Передние и задние датчики","TPMS"]],["Комфорт",["Климат 2 зоны","Обогрев переда и 2 ряда","Обогрев руля и лобового","Электропривод багажника","Дистанционный запуск"]],["Мультимедиа",["Дисплей 12.3\"","Беспроводная зарядка","Расширенная акустика"]]];
      const ult=[["Дизайн",["Литые диски большей размерности","Панорамная крыша","Память зеркал","Декоративная подсветка"]],["Безопасность",["Эра Глонасс","Круговой обзор 540°","Передние и задние датчики","Подушки + шторки"]],["Комфорт",["Климат 2 зоны","Электросиденье водителя с памятью","Обогрев переда, 2 ряда, руля","Электропривод багажника без рук","Атмосферная подсветка"]],["Мультимедиа",["Дисплей 12.3\"","Беспроводная зарядка","Расширенная акустика"]]];
      const map={t9p:prm,t9u:ult,a8a:act,a8p:prm,a8u:ult,t7l:act};
      return map[id]||act;
    }

    function offerPack(id){
      const src=(typeof OFFER_SRC!=="undefined" && OFFER_SRC[id]) || ({t4la:"лифлет T4L",t4lp:"лифлет T4L",t4p:"прайс TENET T4",t7a:"лифлет T7",t7p:"лифлет T7",t7a4:"лифлет T7",t7p4:"лифлет T7",t9p:"прайс Chery Tiggo 9, сокращённый лист",t9u:"прайс Chery Tiggo 9, сокращённый лист",a8a:"прайс Chery Arrizo 8, сокращённый лист",a8p:"прайс Chery Arrizo 8, сокращённый лист",a8u:"прайс Chery Arrizo 8, сокращённый лист",t7l:"прайс Chery Tiggo 7 L, сокращённый лист"}[id]||"официальный прайс");
      return {specs:offerSpecOf(id), groups:offerGroupsOf(id), src:src};
    }
    function offerPackText(pack){
      if(!pack) return "";
      const lines=["","Характеристики"];
      pack.specs.forEach(([k,v])=>lines.push("• "+k+": "+v));
      lines.push("","Оснащение комплектации");
      pack.groups.forEach(([title,items])=>{ lines.push(title+":"); items.forEach(it=>lines.push("— "+it)); });
      if(pack.src) lines.push("","Источник: "+pack.src+". Не оферта.");
      return lines.join("\n");
    }
    function offerPackHtml(pack){
      if(!pack) return `<p class="calc-note">По этой версии листа оснащения пока нет.</p>`;
      const spec=pack.specs.map(([k,v])=>`<li><b>${escape(k)}.</b> ${escape(v)}</li>`).join("");
      const eq=pack.groups.map(([title,items])=>`<p class="offer-eq-h">${escape(title)}</p><ul class="offer-eq">${items.map(it=>`<li>${escape(it)}</li>`).join("")}</ul>`).join("");
      return `<p class="eyebrow">Характеристики</p><ul class="offer-eq">${spec}</ul><p class="eyebrow">Оснащение</p>${eq}<p class="calc-note">${escape(pack.src||"")} Все отмеченные позиции прайса.</p>`;
    }
